1	export interface Customer {
2	  readonly yearsWithMHPCO: number;
3	  readonly previousContracts: number;
4	}
5	
6	export interface Item {
7	  readonly type: string;
8	}
9	
10	const PROCESSING_FEE = 5;
11	
12	// eslint-disable-next-line @typescript-eslint/no-unused-vars -- used by later behaviors
13	export function quote(customer: Customer, items: readonly Item[]): number {
